/* date picker and range picker */
.dp{width:100%;max-width:330px;padding:12px}
.dp-sel{display:grid;grid-template-columns:.8fr 1.3fr 1fr;gap:6px}
.dp-s{position:relative;padding:0}
.dp-s select{padding:8px 26px 8px 10px;font-family:var(--sans);font-size:13px;width:100%}
.dp-s .ms{position:absolute;right:7px;top:50%;transform:translateY(-50%);width:1em;color:var(--muted);pointer-events:none;font-size:15px}
.dp-s:focus-within{border-color:var(--accent-icon-line)}
.dp-val{margin:8px 0 12px;text-transform:none}
.dp-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.dp-head .t{font-weight:600;font-size:14px}
.dp-head .ib{width:28px;height:28px}
.dp-dow{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;font-size:10px;margin-bottom:4px}
.dp-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;transition:opacity .2s ease,transform .3s var(--ease)}
.dp-grid.out-l{opacity:0;transform:translateX(-14px)}
.dp-grid.out-r{opacity:0;transform:translateX(14px)}
.dd{position:relative;height:36px;display:grid;place-items:center;font-size:13px;color:var(--text);transition:background-color .2s,color .2s}
.dd:hover{background:rgba(var(--fg-rgb),.05)}
.dd.mute{color:var(--muted);opacity:.5}
.dd.wk{color:var(--text-dim)}
.dd.today{box-shadow:inset 0 0 0 1px var(--accent-icon-line)}
.dd.today::after{content:"";position:absolute;bottom:5px;width:4px;height:4px;background:var(--accent)}
.dd.sel,.dd.r-s,.dd.r-e{background:var(--accent-hi);color:#120a02;font-weight:600}
.dd.sel::after,.dd.r-s::after,.dd.r-e::after{background:#120a02}
.dd.r-in{background:var(--accent-bg);color:var(--text)}
.dd.mute.r-s,.dd.mute.r-e{opacity:1}
.dd.mute.r-in{opacity:.85}
.dd.r-pv{background:rgba(var(--fg-rgb),.05)}
.dd:focus-visible{outline:1px solid var(--accent);outline-offset:-1px}
.dp-foot{display:flex;justify-content:space-between;margin-top:10px}
.rp{width:100%;max-width:470px}
.rp-body{display:grid;grid-template-columns:130px 1fr}
.rp-presets{display:flex;flex-direction:column;padding:10px 8px;border-right:1px solid var(--line);gap:2px}
.rp-pre{padding:8px 10px;text-align:left;font-size:13px;color:var(--text-dim);transition:color .2s,background-color .2s}
.rp-pre:hover{color:var(--text);background:rgba(var(--fg-rgb),.03)}
.rp-pre.on{color:var(--accent);background:var(--accent-bg)}
.rp-cal{padding:12px}
.rp .dd{height:32px}
.rp-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 14px;border-top:1px solid var(--line);font-size:13px}
.rp-foot .btn{padding:8px 14px;font-size:13px}

/* ---------- date range picker ---------- */
{
  const grid = $('#rp-grid'), mlab = $('#rp-month'), sum = $('#rp-sum'), apply = $('#rp-apply'), pres = $('#rp-presets');
  let vy = TODAY.getFullYear(), vm = TODAY.getMonth(), a = null, b = null, hov = null;
  const presets = [
    ['Today', () => [TODAY, TODAY]], ['Last 7 days', () => [addDays(TODAY, -6), TODAY]], ['Last 30 days', () => [addDays(TODAY, -29), TODAY]],
    ['This month', () => [new Date(TODAY.getFullYear(), TODAY.getMonth(), 1), TODAY]],
    ['Last month', () => [new Date(TODAY.getFullYear(), TODAY.getMonth() - 1, 1), new Date(TODAY.getFullYear(), TODAY.getMonth(), 0)]]
  ];
  pres.innerHTML = presets.map((p, i) => `<button class="rp-pre" data-i="${i}">${p[0]}</button>`).join('');
  const fm = d => d.toLocaleDateString('en-GB', { day:'numeric', month:'short' });
  function summary(){
    apply.disabled = !(a && b);
    swapText(sum, !a ? 'Pick a start date' : !b ? fm(a) + ', pick an end date' : `${fm(a)} to ${fm(b)}, ${Math.round((b - a) / 864e5) + 1} days`);
  }
  function build(){
    mlab.textContent = new Date(vy, vm, 1).toLocaleDateString('en-GB', { month:'long', year:'numeric' });
    const end = b || (a && hov && hov >= a ? hov : null);
    grid.innerHTML = monthCells(vy, vm).map(d => {
      const t = d.getTime(), inR = a && end && t > a.getTime() && t < end.getTime();
      const cls = ['dd', d.getMonth() !== vm ? 'mute' : '', dayKey(d) === dayKey(TODAY) ? 'today' : '', a && t === a.getTime() ? 'r-s' : '', b && t === b.getTime() ? 'r-e' : '', inR ? (b ? 'r-in' : 'r-pv') : ''].join(' ');
      return `<button class="${cls}" data-k="${t}">${d.getDate()}</button>`;
    }).join('');
  }
  grid.addEventListener('click', e => {
    const btn = e.target.closest('.dd'); if (!btn) return; const d = new Date(+btn.dataset.k);
    if (!a || b){ a = d; b = null; } else if (d < a){ a = d; } else { b = d; }
    $$('.rp-pre', pres).forEach(x => x.classList.remove('on')); Sound.play(b ? 'select' : 'tick'); build(); summary();
  });
  grid.addEventListener('mouseover', e => { const btn = e.target.closest('.dd'); if (!btn || !a || b) return; const d = new Date(+btn.dataset.k); if (!hov || d.getTime() !== hov.getTime()){ hov = d; build(); } });
  grid.addEventListener('mouseleave', () => { if (a && !b){ hov = null; build(); } });
  pres.addEventListener('click', e => { const p = e.target.closest('.rp-pre'); if (!p) return; [a, b] = presets[+p.dataset.i][1](); vy = b.getFullYear(); vm = b.getMonth(); $$('.rp-pre', pres).forEach(x => x.classList.toggle('on', x === p)); Sound.play('select'); build(); summary(); });
  const move = n => { const nm = vm + n; grid.classList.add(n > 0 ? 'out-l' : 'out-r'); setTimeout(() => { vy += Math.floor(nm / 12); vm = ((nm % 12) + 12) % 12; build(); grid.style.transition = 'none'; grid.classList.remove('out-l', 'out-r'); grid.classList.add(n > 0 ? 'out-r' : 'out-l'); grid.offsetWidth; grid.style.transition = ''; grid.classList.remove('out-l', 'out-r'); }, 180); Sound.play('tab'); };
  $('#rp-prev').addEventListener('click', () => move(-1)); $('#rp-next').addEventListener('click', () => move(1));
  apply.addEventListener('click', () => { Sound.play('done'); showToast('Range applied'); });
  build(); summary();
}
